edits.after:
self._onInputBlur = function()
{
    // IE allows pika div to gain focus; catch blur the field
    var pEl = document.activeElement;
    do {
        if (hasClass(pEl, 'pika-single')) {
            return;
        }
    } while ((pEl = pEl.parentNode));

    if (tabPressed) {
        tabPressed = false;
        return;
    }

    if (!self._c) {
        self._b = sto(function() {
            self.hide();
        }, 50);
    }
    self._c = false;
};
